/// @brief Enumeration for calendar errors.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
abstract class calendar_error_e {
  /// < Successful
  static const int CALENDAR_ERROR_NONE = 0;

  /// < Out of memory
  static const int CALENDAR_ERROR_OUT_OF_MEMORY = -12;

  /// < Invalid parameter
  static const int CALENDAR_ERROR_INVALID_PARAMETER = -22;

  /// < Requested data does not exist
  static const int CALENDAR_ERROR_NO_DATA = -61;

  /// < Operation now in progress
  static const int CALENDAR_ERROR_NOW_IN_PROGRESS = -115;

  /// < Operation already in progress
  static const int CALENDAR_ERROR_ALREADY_IN_PROGRESS = -114;

  /// < Operation not permitted
  static const int CALENDAR_ERROR_NOT_PERMITTED = -1;

  /// < FS is full
  static const int CALENDAR_ERROR_FILE_NO_SPACE = -28;

  /// < Permission denied
  static const int CALENDAR_ERROR_PERMISSION_DENIED = -13;

  /// < No access to the database
  static const int CALENDAR_ERROR_DB_FAILED = -33554430;

  /// < Iterator is on the last position
  static const int CALENDAR_ERROR_ITERATOR_END = -33554428;

  /// < Database not found
  static const int CALENDAR_ERROR_DB_RECORD_NOT_FOUND = -33554427;

  /// < Unknown IPC error
  static const int CALENDAR_ERROR_IPC = -33554241;

  /// < Error from another modules
  static const int CALENDAR_ERROR_SYSTEM = -33554193;

  /// < Not supported (Since 4.0)
  static const int CALENDAR_ERROR_NOT_SUPPORTED = -1073741822;
}

