  static const int CALENDAR_MATCH_FULLSTRING = 1;

  /// < Sub string, case-insensitive
  static const int CALENDAR_MATCH_CONTAINS = 2;

  /// < Start with, case-insensitive
  static const int CALENDAR_MATCH_STARTSWITH = 3;

  /// < End with, case-insensitive
  static const int CALENDAR_MATCH_ENDSWITH = 4;

  /// < IS NOT NULL
  static const int CALENDAR_MATCH_EXISTS = 5;

  /// < Calendar match string flag max enum count
  static const int CALENDAR_MATCH_STR_MAX = 6;
}

/// @brief Enumeration for the filter match type of an integer.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @elseif TV 4.0 @endif
abstract class calendar_match_int_flag_e {
  /// < '='
  static const int CALENDAR_MATCH_EQUAL = 0;

  /// < '>'
  static const int CALENDAR_MATCH_GREATER_THAN = 1;

  /// < '>='
  static const int CALENDAR_MATCH_GREATER_THAN_OR_EQUAL = 2;

  /// < '<'
  static const int CALENDAR_MATCH_LESS_THAN = 3;

  /// < '<='
  static const int CALENDAR_MATCH_LESS_THAN_OR_EQUAL = 4;

  /// < '<>', this flag can yield poor performance
  static const int CALENDAR_MATCH_NOT_EQUAL = 5;

  /// < IS NULL
  static const int CALENDAR_MATCH_NONE = 6;

  /// < Calendar match integer flag max enum count
  static const int CALENDAR_MATCH_INT_MAX = 7;
}

